#!/usr/bin/env bash
# 编译并部署到 r2modman 的 lianji-mod profile。
set -e

ROOT="$(cd "$(dirname "$0")" && pwd)"
SRC="$ROOT/src/LogisticsHub"
PROFILE="${PROFILE:-/c/Users/Administrator/AppData/Roaming/r2modmanPlus-local/DysonSphereProgram/profiles/lianji-mod}"
DEST="$PROFILE/BepInEx/plugins/LogisticsHub"   # 独立子目录：全部文件收拢在这里
DOTNET="/c/Program Files/dotnet/dotnet"
PY="/c/Users/Administrator/AppData/Local/Python/bin/python"

# 版本号唯一来源：C.cs 的 Version 常量（和 package.sh 读的是同一处）
VERSION="$(sed -n 's/.*public const string Version = "\([0-9.]*\)".*/\1/p' "$SRC/C.cs" | head -1)"
[ -n "$VERSION" ] || { echo "!! 读不到版本号（C.cs 的 Version 常量）" >&2; exit 1; }

echo "== 1/4 重新导出几何（改过 tools/station_model.py 才需要）"
if [ -f "$ROOT/tools/station_model.py" ]; then
  ( cd "$ROOT/tools" && "$PY" gen_cs_geometry.py )
fi

echo "== 2/4 编译"
"$DOTNET" build "$SRC/LogisticsHub.csproj" -c Release --nologo -v q

echo "== 3/4 部署到 $DEST"
mkdir -p "$DEST"
# 游戏正在运行时 dll 会被占用（Device busy）：部署失败只警告，不打断打包流程
if ! cp "$SRC/bin/Release/DSPLogisticsHub.dll" "$DEST/" 2>/dev/null; then
  echo "  [警告] DSPLogisticsHub.dll 部署失败（游戏占用中？）。bin/Release 里的产物已就绪，退出游戏后重跑 build.sh 即可同步。"
fi
cp "$SRC/bin/Release/DSPLogisticsHub.pdb" "$DEST/" 2>/dev/null || true

cat > "$DEST/LogisticsHub.manifest.json" <<JSON
{
  "name": "AerialMiningLogisticsStation",
  "version_number": "$VERSION",
  "website_url": "https://github.com/bo5501/Aerial-Mining-Logistics-Station",
  "description": "空中采矿机物流运输站：12 个辊道接口 + 地脉钻孔底座（6 口地脉井 + 24 条熔岩裂缝 + 地热直接充进站内电池，2 MW × 地热强度 × 矿物利用倍率：每级 +15%，最高 ×4）+ 原版黑雾中继站光柱与 4 条信息/物资传输带 + 悬浮碟形枢纽（对齐中继站 70 m）+ 50 泊位双层停靠环（2×25）+ 50 艘星际货船 / 200 架运输机 + 20 卡槽×50 万（原版站体窗口内：左侧 10 格卡槽手动配货，右侧只读采矿列）+ 自动采集矿脉 / 原油 / 海洋（水·硫酸）+ 22 座可动激光炮塔 + 36 m 半球护盾。0.9.16：科技节点改为照 ProjectGenesis 的流程实现——Harmony 高优先级前缀掐掉 LDBTool.Bind（不再让 CustomID.cfg 覆盖 proto ID），注册时机改到 LDBTool.PreAddDataAction（LDB 已就绪，前置与坐标一次到位），PostAddDataAction 里按 ProjectGenesis 的 ProtoPreload 做 科技表 OnAfterDeserialize + 全表 Preload + 全表 Preload2（前置科技的 postTechArray 才会带上新节点、原版科技也补上我们的解锁配方），科技图标改用本站自绘的建筑图标而不是借前置那张气态行星。0.9.17：修科技树节点「缺流程线」——格距按原版改成 4 单位（原版 143 条科技的相邻位移全是 (4,0)/(4,±4)/(4,±8)，1 单位 = 114 px；原来用 2 单位，前置画的连线长度 = 目标.x−(前置右边+140) 会算成负数，箭头直接被判成不可见）。0.9.18：矿物利用的两个加成改为直接读存档累计值（miningSpeedScale / miningCostRate），修正之前把「每级 -6% 消耗」写成线性 1-0.06×Lv 的错误（原版是连乘 0.94^Lv，Lv6 应为 69.0% 而不是 64%）；面板「矿物利用」行同步改成「速度×1.60 耗矿×0.690」。0.9.19：科技研究材料改为电磁矩阵 / 能量矩阵 / 结构矩阵各 2400（原版公式 count = HashNeeded×ItemPoints/3600，取 HashNeeded=3600、ItemPoints=2400）；自动采矿右列每格容量跟「矿物利用」等级绑定（解锁 2 万，每级 +3 万，Lv16 到顶 50 万，面板表头显示每格容量）；兼容创世之书（ProjectGenesis）布局 —— 所有 mod 的科技进表之后再复查一次坐标，重叠或前置被挪走会自动重排，占位阈值 2→3.5，不再挑到两个节点正中间的格子；科技 ID 撞车会自动换空号。0.9.20：武器系统重做 —— 22 座炮塔换成参考图的三叉重炮造型（20 段倒角底座 + 8 颗固定螺栓 + 4 个外伸固定爪；16 段涡轮主筒 + 8 条纵向加强筋 + 4 片法兰各带阴影槽；后置机匣含包边/侧装甲/格栅/金条；尾部后坐筒 + 三段箍 + 方尾盖；三根分段变径炮管，根套筒 + 球铰 + 深色分节环 + 两道金箍 + 开架式管口），面数 1364→2484。开火特效同步重做：白色核心 + 青色辉光 + 淡紫外晕三层能量束，从炮口实际位置射出，并按距离自动加粗；炮口/命中点各一个「球 + 同心环 + 12 条星芒」闪光。0.9.21：修炮塔实机发黑 —— 根因不是反照率，而是这条渲染路径上的光照项基本为 0：主建筑材质共用一张 _MS_Tex，hull 取色点金属度是满的（R=255），纯金属面漫反射为 0、镜面反射要靠探针，而炮塔是普通 MeshRenderer，场景里没有探针；再加上塔顶 18 座一直在碟体投影里、基座 4 座在裙边投影里，连太阳高光都被剪掉。改法：炮塔材质 _MetallicMultiplier 归零（漫反射重新占主导）、_SmoothMultiplier 压到 0.55、_AlbedoMultiplier ×1.10、自发光按槽位抬到 0.44~0.62（炮口镜片仍 2.60），并把 _ToggleVerta/_ToggleAnim/_AlphaClip 显式归零；炮塔渲染器改成 receiveShadows=false（不再被站体投影压黑）；物资光点材质同样金属度归零、光滑度压平，避免没有 _MS_Tex 时默认取样成「满金属满光滑」反射到黑。0.9.22：修「炮口一圈黑环 + 12 条黑星芒 + 天上黑针」——0.9.20 起的激光束/闪光材质是「克隆主建筑材质、再把 shader 换成 PBR Standard Glass」，克隆把 _MainTex/_MS_Tex 一起带了过来，而 FX 网格（闪光、货箱、光束）的 UV 全是 (0,0)，整块面片都采到贴图同一个像素 —— 那里是「RGB 黑、A 不透明」，于是闪光变成不透明纯黑实体；Glass 又走 PBR 光照路径、普通 MeshRenderer 没有反射探针，且 _ZWrite 根本不是 shader 属性（SetFloat 静默失效），三层光束靠深度互相压死。改法：FX 材质全部从零 new Material(Unlit Additive)，一张贴图都不挂，亮度只由 _TintColor × _Multiplier 决定 —— 加法混合下「黑」= 不可见，物理上不可能再出现黑块；同时枪口闪光基准缩放 1.60 → 0.78（原来星芒伸到 1.86 m，比炮塔本体还大一圈，像给炮管套了个大光环）。0.9.24：① 修「敌人已经死了/打不动，炮塔还在持续输出」——根因是选目标时只看 id 不看 isInvincible（原版 TurretComponent 的判定是 id == index && !isInvincible），黑雾正在孵化/生长的无敌单位会被一直锁着打；现在扫描跳过无敌目标、每帧验一次目标存活（不再等 0.35 s 的扫描节拍）、并且同一目标连续开火 8 s 仍不死的会拉黑 6 s 换目标。② 塔顶 18 座换成原版「磁化电浆炮」的炮：运行时按名字从 LDB 找到 turret-plasma 预制体，取它 lod0 的五块网格（底座/围壳/活塞/炮身×2）+ 原版贴图，shader 换成验证过的 PBR Standard（原版 PBR Turret Plasma 的俯仰是顶点着色器按 _Pivot 转的，普通 MeshRenderer 用不了），缩放 0.26（高 2.16 m），炮身绕原版枢轴俯仰。③ 武器分家：塔顶电浆炮只打空中目标（protoId 8129/8130 或高出地面 95 m），射程 600 m，开火是原版电浆弹（turretCannonades，damage=0 只做表现）；基座 4 座激光塔只打地面目标，射程 140 m，仍是连续激光。空中/地面目标分开排队，22 座不会全扑同一个点。0.9.23：激光武器特效整体换成原版高频激光塔的射线 —— 不再自己拼三层能量束，而是照抄原版 TurretComponent 的激光分支，往工厂的 skillSystem.turretLaserContinuous 池里挂一条 LocalLaserContinuous，之后每帧只更新 beginPos / endPos。光束的网格、材质（游戏自己 Instantiate 的 turret-laser-continuous）、沿光束流动的流光、命中点的火花粒子，全部由原版 SkillSystem.TickSkillLogic 驱动，外观与真正的高频激光塔完全一致；damage 置 0、target.id 置 0，只借表现不结算（伤害仍在 Fire() 里按 160 / 0.22 s 走）。炮塔转向没到位、失去目标、站被拆时会把射线 Stop 掉，避免残留光束。同时删除了 0.9.20~0.9.22 那套自制特效（三层 LineRenderer + 球/环/星芒闪光 + 相关材质与常量）。0.9.25：修三处实机反馈 —— ① 站体窗口补上「当前使用电网功率」：原版口径是 requiredEnergy×60×consumerRatio，0.9.12 把电力行两格换成地热读数后这个数就丢了，现在状态行写「● 运行中（电网 42.3MW）」、电力行第一格写「电网 42MW」、电池行写「+42.3 MW」；② 基座激光塔改成三管三射线：模型本来就是三叉三管，之前只从中间管口挂一条原版连续激光，现在按 tools/station_model.py 的三个管口点（中管 1.07/3.30、左右管 ±0.92/0.51/3.112）各挂一条，远看是三条汇聚的激活线；③ 「电磁武器效果」跟科技等级绑定：矿物利用每升一级，激光与电浆炮伤害 +5%（MiningTech.WeaponMul，封顶 ×4），面板新增一行「电磁武器 +30% · 电浆弹 2 MJ/发（电量）」，科技说明同步写明；④ 电浆炮的「子弹」= 站内电量：每发扣 2 MJ（和货船起飞同一个电池池），电量不足就停火并在日志提示一次，接电网或建在地热上即可持续供弹。0.9.26：① 资源小图标改成原版 iconSet 图集 —— 之前用 Image.sprite = item.iconSprite，那是一张没有 mipmap 的 80×80 图，缩到 22 px 严重走样、实机看就是一块色斑；现在按原版 UIStorageGrid / UIItemPicker 的做法，用 RawImage 直采 GameMain.iconSet.texture（2000² 带 mipchain 的 25×25 图集），按 itemIconIndex[itemId] 算 uvRect（格 x/y ÷ 25），并把图标从 22 px 放大到 26 px、加一层 30 px 底槽，缩小后走 mip 过滤，矿种轮廓清楚可辨；② 塔顶电浆炮的伤害明确吃到「电磁武器效果」（每级 +5%）：面板那行改成「电磁+30% 激光208 电浆1170 弹2MJ/发」，升级后电浆数字同步变化，日志也会打一行「电浆炮: 电磁武器 ×1.30 → 塔顶单发 1170 伤害」。0.9.27：① 修「面板矿物利用 Lv6 与科技-升级页等级不同步」——根因是 TechState.curLevel 的初值不是 0，而是 TechProto.Level（矿物利用 3606 的 Level=6，即它在科技树上的层位），GameHistoryData.Init 里直接用它初始化，于是一级都没升的存档也读成 Lv6 —— 这正好解释了「面板 Lv6、右边却是 速度×1.00 耗矿×1.000」的矛盾。现在按原版 UITechNode 的口径取curLevel - techProto.Level 作为已升级级数，并用 miningSpeedScale（每级 +0.1）交叉校验兜底（两个口径取小值），面板等级、科技页等级、速度倍率三者一致；同时修正了因虚高 6 级而多算的「电磁武器 +30%」与「自动格容量 20 万」—— 0 级应分别是 +0% 和 2 万，升级后正常增长。② 采矿基准改成原版大型采矿机（高级采矿机 itemId 2302）：每矿脉每秒产出 = 600000 / prefabDesc.minerPeriod（原版 UI「每分每矿脉」= 60 × 该值），本站 12 个吸气钟等价 12 条矿脉，base = 12 × 该值，再乘地热倍率与矿物利用速度；面板「每 1 s 取 N 个」与产出共用 StationMiner.CycleCap，不再各算一遍。0.9.28：① 修「科技-升级-矿物利用已解锁，面板仍写未研究」——两个原因：(a) 等级只在 StationMiner.Tick 里刷新，而那段代码在「站已通电并在钻孔」之后，站一断电或刚解锁科技还没钻孔时面板读的就是缓存值；现在 StationPanel 每帧刷新也调一次 MiningTech.Refresh（内部 2 s 节流）。(b) 只减 TechProto.Level 基线还不够：解锁第 1 级时若 curLevel 未被 +1（多人同步/存档迁移），curLevel−Level 仍是 0 就被当成没研究；现在以 curLevel−Level（原版 ABN_VeinsUtil 反作弊检查用的同一口径）为主，miningSpeedScale 反推的级数只在两者相差超过 1 级时接管（别的 mod 改倍率 / 存档迁移）；面板文案区分「未解锁 / 已解锁 / Lv n」。② 修正采矿基准取错物品：0.9.27 写死的 2302 实测是「电弧熔炉」（minerPeriod=0），日志已暴露「原版电弧熔炉（itemId 2302）… minerPeriod=0」并退回 1 个/秒；现在扫 LDB.items.dataArray 取 minerPeriod>0 且最小的那台（= 效率最高的原版矿机，即大型/高级采矿机），日志打印实际选中的物品 id、名字与 minerPeriod。日志新增诊断：采矿科技: … [诊断 id=3606 curLevel=7 maxLevel=… protoLevel=6 unlocked=True lvTech=1 lvBySpeed=1 spd=1.100]。0.9.29：把「底座地热 → 塔顶武器」这条电路打通 —— 之前电浆炮每发 2 MJ，18 座 × 1.10 s ≈ 33 MW，而地热强度 3.0 的底座只发 6 MW，站内电池被抽干后塔顶就彻底停火，玩家看到的是「底座在打洞发电、塔顶却像没通电」。现在：① 电浆弹改成 0.35 MJ/发，18 座满速 ≈ 5.7 MW，正好落在地热 6 MW 以内 —— 底座打出来的电刚好够塔顶满火力，地热弱（强度 1.05 ≈ 2.1 MW）就自动降成约 6 发/s，接电网永远满速；② 断电（既没电网、地热也不足）时炮塔停火只做待机扫掠，不再打空包弹；③ 塔顶电浆炮通电时炮身自发光抬到 1.10、断电熄回 0.28，模型上直接看得出有没有电；④ 面板武器行尾巴改成「塔顶 x.xMW」（接电网 = 电网取用 + 地热，地热自持 = 地热），日志新增「塔顶供电: 地热 6.00MW · 电浆弹 0.35MJ/发，18 座满速需 5.7MW（够用，满火力）」。0.9.30：① 电浆弹能耗按用户要求从 0.35 MJ 提到 **10 MJ/发**（面板武器行写明「弹10MJ」，日志「塔顶供电」会按当前功率算出够几发/s）；② 面板左列第 10 格改成「核电燃料格」：只请求氘核燃料棒（本地无人机 + 星际运输船都认，第 7~10 格原先不参与物流的原版硬编码已用 Harmony 补上），一根棒按 ItemProto.HeatValue（600 MJ）烧 40 s、输出 15 MW（对齐原版微型核聚变发电站），电直充站内电池，塔顶电浆炮/采矿/护盾共用；电池满自动停烧省棒，面板标题行显示「核电 15MW · 氘棒 N」或「核电无燃料 · 第10格」，第 10 格被别的货物占着时不会清空玩家库存，只提示一次；③ 供电判定加入核电：没电网、地热不够但有氘棒的站也能正常采矿/开盾/开火，日志「物流站已启动: … 供电=核电」与「塔顶供电: 核电 …」同步。0.9.31：站体窗口右侧的「当前采矿」重排成两张表，并整体放大字号。① 上半是键值表：供电（● 电网 / ● 地热 / ● 核电 / ○ 未通电，20 px 粗体）、功率（电网45.2+地热6.00=塔顶51MW，把「谁供的、供多少、塔顶能拿到多少」写在一行）、钻孔（N 个/1.0s · ×地热倍率）、电池（百分比 + 电量 + 充电功率）——标签列固定 46 px，四行读数左边缘对齐；② 下半是四列表格（资源 / 储量 / 处 / 库存），带深色表头条、斑马纹行底、数字列统一右对齐，海洋行写「取之不尽」；③ 科技 / 武器两行各拆成左右两格分别对齐（之前一整串挤在 340 px 里只能压到 13 px）；④ 字号整体抬一档：标题 24 粗体、状态 20 粗体、读数 17、表头 16、矿名 18，全部不再小于 16 px；⑤ 配色按「背景吃掉小字」的反馈重做：列底从 0.62 alpha 提到 0.92（近实心深色卡），表头再深一档、偶数行铺淡膜做斑马纹，文字投影加深到 0.72，16~20 px 的字在亮色行星背景上不再发糊；列宽 340 → 380 给四列表格腾出对齐空间。（对应的 1:1 预览图见 tools/v0931_panel.png）0.9.32：修「第 10 格放了氘核燃料棒却提示无燃料、完全没有发电效果」。根因是 0.9.30 按**名字**找燃料（IndexOf(「Deuteron」) / 「Fuel Rod」），而 ItemProto.name 是本地化字段，中文版里它是「氘核燃料棒」，两个关键字都匹配不上，查找整个落空、第 10 格燃料机制静默停用（日志只有一行「LDB 里找不到氘核燃料棒」）。现在改成**只看热值**、与语言无关：凡 HeatValue ≥ 400 MJ 的物品都算燃料棒，原版正好命中三根（氘核 600 MJ / 反物质 7.5 GJ / 奇异湮灭 9 GJ），化学燃料（煤 5.4 MJ、氢棒 54 MJ）全部低于这条线不会误认；第 10 格里放三者中任意一根都能发电，空格时默认只请求最便宜的氘棒，已是燃料棒的格子不再被当成「占用」拦下；每根烧多久按该棒自己的热值算（15 MW 恒定：氘棒 40 s、反物质棒 500 s、奇异湮灭 600 s），面板标题行与配电日志按实际燃料显示「氘棒 / 反物质棒 / 奇异棒 N」，启动日志新增「识别到 N 种燃料棒（…）」一行。0.9.33：修「第 10 格被铺成蓄电器（满），氘棒根本放不进去」。日志实测识别到 4 种「燃料棒」，其中「蓄电器（满）」热值 540 MJ，比氘核燃料棒的 600 MJ 还低，于是被 0.9.32 的「取最便宜那根当默认请求项」排到了第一位 —— 第 10 格被铺成「蓄电器（满）· 需求 100」并锁住 itemId，原版 UI 不允许往 itemId 不同的格子里放货，玩家拖氘棒进去没有任何反应，面板一直显示「核电无燃料」。满蓄电器是电池不是燃料棒，现已在三段筛选里全部排除；识别顺序改为：① 名字含「燃料棒 / Fuel Rod」且热值 ≥ 400 MJ（中英文版都能精确命中三种棒）；② 仅热值 ≥ 400 MJ（排除满蓄电器）；③ 40 MJ 兜底。排除后默认请求项就是氘核燃料棒，第 10 格读档即自动纠正回氘棒；三种棒每根燃烧时长按各自热值算：氘核 600 MJ / 40 s、反物质 7200 MJ / 480 s、奇异湮灭 72000 MJ / 4800 s（恒 15 MW 输出）；格子被别的货占着时日志会写清「搬空第 N 格后自动变成燃料格」。0.9.34：修「第 10 格只能放氘棒，反物质棒 / 奇异湮灭棒放不进去」。原版 UIStationStorage.OnItemIconMouseDown 的第一道判断是「手上物品必须与格子 itemId 同种」，而物流站格子一旦被设成氘核燃料棒，就再没有入口换种类（「选择物品」按钮只在 itemId=0 的瞬间可见），于是只有氘棒能塞进去。现在补了一条交互补丁：手拿任意一种燃料棒点第 10 格，会先用原版 SetStationStorage 换种类（它自动把格子原有燃料退回背包，不吞货），再走原版塞货逻辑，三种棒都能直接放、放进去就按各自热值烧（40 s / 480 s / 4800 s）；另外玩家点「取回」清空格子后留 12 s 窗口，不再被自动铺回的氘棒抢掉换棒机会。0.9.35：第 10 格核电输出 15 MW → 80 MW（玩家指定）。能量守恒不变：一根棒能发的电由热值决定，输出功率提高后燃烧时间等比缩短 —— 氘核燃料棒 7.5 s、反物质燃料棒 90 s、奇异湮灭燃料棒 900 s（原为 40 / 480 / 4800 s）；一格 100 根在 80 MW 下分别撑 12.5 分钟 / 2.5 小时 / 25 小时，靠物流自动补货。参考量级：塔顶 18 座电浆炮满速需 163.6 MW，15 MW 只够约 1.5 发/s，80 MW 约 8 发/s。面板标题行、功率算式、供电日志全部按新功率自动显示（统一读 C.FusionPowerMw，无硬编码）。0.9.36：核电输出 80 MW → 100 MW（玩家指定）。能量守恒不变，燃烧时间按比例再缩一档：氘核燃料棒 6 s、反物质燃料棒 72 s、奇异湮灭燃料棒 720 s（15 MW 时为 40/480/4800 s）；一格 100 根在 100 MW 下分别撑 10 分钟 / 2 小时 / 20 小时。塔顶 18 座电浆炮满速 163.6 MW，100 MW 约 10 发/s，加上地热 6 MW 约 10.6 发/s。0.9.37：地热转换功率也跟「矿物利用」等级同步（玩家要求「地热 6 MW 也要绑定等级」）。口径与采矿速度同一套线性累加：地热功率 ×(1 + 0.15 × Lv)，封顶 ×4 —— 满强度(Lv0) 6 MW → Lv6 11.4 MW → Lv20 24 MW；「GeoPowerMw」（面板读数 / 功率算式 / 启动日志）与 「ChargeGeo」（真正灌进站内电池的能量）读同一个倍率，不会出现「面板涨了、电池没涨」。面板科技行右格随之从两条变三条：速度×1.60 耗矿×0.69 地热×1.9；列宽 380 → 440（行宽 356 → 416）才放得下 —— 0.9.31 那版把标签列 46 px 漏在右格宽度之外，实机上右侧文字其实已经压到左格上，这次一并修正：科技/武器行左格 0.30、右格 0.70；资源表四列重新分配（名称 112 / 储量 100 / 处 44 / 库存 116），数字列右边界仍在同一条竖线上。0.9.38：炮塔伤害改绑原版科技「升级 → 能量武器伤害」（每级 +10%），不再自造「矿物利用每级 +5% 电磁武器」那套绑定 —— 原版 TurretComponent 的 Shoot_Laser / Shoot_Plasma / Shoot_LocalPlasma 三处本来就是 damage × history.energyDamageScale，所以基座激光塔与塔顶电浆炮在原版里就同吃这一条；本站直接读存档累计值 energyDamageScale（和 0.9.18 的 miningSpeedScale 同一个路子），换存档、别的 mod 改等级都自动跟随。面板武器行「电磁+30%」→「能量+30%」，BepInEx 日志新增独立一行「能量武器: ×1.30 …→ 激光单发 / 电浆单发」，不再和「采矿科技」混在一起。0.9.39：底座与塔顶造型精细化 —— 底座 12 段 → 24 段（面心对齐 12 个辊道口与 12 个吸气钟），裙边拆成「埋地台 / 台阶 / 主裙 / 内凹暗带 / 肩台倒角 / 腰部灯带 / 顶环」七级，加 24 条顺坡竖肋、3 道接缝环、24 颗面螺栓、12 段琥珀警示条、12 条竖向线管，顶环平台补 12 组设备箱 + 缆盘 + 格栅与 16 根护栏立柱，并给基座 4 座激光炮补了外伸托架（之前炮座盘是悬空的）；塔顶碟盘边缘改为「上/下倒角环 + 深色压边 + 细灯缝」，盘面加 24 条分格缝 + 24 条凸筋 + 24 颗螺栓，中心塔从 0.75 m 的「井盖」改成四级收分塔身（3.36→2.05，三道灯环 + 三级台肩），顶上加桅杆、两道横臂、三道斜拉索与信标球（塔顶 31.3 → 34.96），台阶环上补 4 座传感器穹顶。TotalHeight 32.40 → 35.00 同步（cullingHeight/signHeight 跟着长），否则天线会被裁掉。面数 34432 → 41464。0.9.40：修两个战斗 BUG —— ① 基座激光塔的「监控范围」口径写明并落日志（140 m，黑雾只有进入范围才被锁定攻击）；② 修塔顶电浆炮对太空黑雾舰队没有任何效果：舰队在 factory.sector.enemyPool（星区池）而不在 factory.enemyPool（行星池），之前扫描只扫行星池、伤害入口 DamageGroundObjectByLocalCaster 也只认行星池，太空目标根本搜不到也打不动；现在照原版磁化电浆炮（TurretComponent.Search_Plasma）的链路，把星区敌人经 TransformFromAstro/InverseTransformToAstro 换算到行星坐标纳入扫描（高度 <95 m 归基座激光塔、≥95 m 归塔顶电浆炮，600 m 射程内，高空目标带视界粗判），伤害改走 SkillSystem.DamageObject 按 target.astroId 分发（母巢目标扣 sector.enemyPool 的血，带巢等级减伤与巢经验，与原版 Shoot_Plasma 弹丸命中同一入口），黑名单槽位按 id+astroId 区分两个池；启动日志写明监控范围，物品描述补充「基座 140 m / 碟顶 600 m（含太空舰队）」。0.9.41：修开局跳过序章 NullReferenceException —— BulletTime 的快速加载 Transpiler 把 GameLoader frame 7 等待条件里的 StarData.loaded 换成 GameMain.localPlanet?.loaded ?? true，localPlanet 未赋值时恒为 true，星球加载等待被完全绕过，frame 9 执行 SkipStandardModeGuide 时 localPlanet/factory 未就绪即 NRE；本 mod 在 SkipStandardModeGuide / StartStandardModeGuide 加就绪守卫前缀（mainPlayer / localPlanet / factory 任一为空则拦下），GameMain.FixedUpdate postfix 每帧重试，星球就绪后自动补发（30 秒超时放弃并报错）。",
